"""Single-file report: escaped content, local styles, vanilla filtering."""
from collections import Counter
from html import escape
import json
from pathlib import Path


def write_report(run: dict, path: Path):
    e = lambda value: escape(str(value), quote=True)
    counts = Counter(f["severity"] for f in run["findings"])
    delta = run.get("delta", {})
    resolved = delta.get("resolved", 0)
    baseline = "First scan" if delta.get("previous") is None else f"{delta['current']-delta['previous']:+d} issues since last scan"
    rows = "".join(f'''<article class="finding" data-severity="{e(f['severity'])}">
<div><span class="pill {e(f['severity'].lower())}">{e(f['severity'])}</span><code class="rule">{e(f['rule'])}</code></div>
<div><h3>{e(f['title'])}</h3><code class="location">{e(f['file'])}:{f['line']}</code><pre>{e(f['snippet'])}</pre><p class="fix">{e(f['fix'])}</p></div></article>''' for f in run["findings"])
    kpis = "".join(f'<div><span>{label}</span><strong>{number:02}</strong></div>' for label, number in [("Critical", counts["Critical"]), ("High", counts["High"]), ("Medium", counts["Medium"]), ("Resolved", resolved)])
    warnings = "".join(f"<p>{e(w)}</p>" for w in run.get("warnings", []))
    document = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>MinionAudit · Repository audit</title>
<style>
:root{color-scheme:dark;--bg:#09090b;--surface:#111113;--line:#27272a;--text:#fafafa;--muted:#a1a1aa}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px Inter,system-ui,sans-serif;line-height:1.6}code,pre,.meta,.kpis strong,.rule{font-family:"JetBrains Mono",ui-monospace,monospace}header{border-bottom:1px solid var(--line);padding:18px 32px;display:flex;gap:24px;align-items:center}.brand{font-weight:650;letter-spacing:-.4px}.brand span{color:var(--muted);font-weight:400;margin-left:14px}.badge{margin-left:auto;border:1px solid var(--line);padding:3px 9px;border-radius:4px;color:var(--muted);font-size:12px}main{max-width:1140px;margin:38px auto;padding:0 28px}.eyebrow{font:11px ui-monospace,monospace;letter-spacing:1.5px;color:var(--muted);text-transform:uppercase}h1{font-size:26px;letter-spacing:-.8px;margin:4px 0}h2{font-size:15px;font-weight:600}h3{font-size:14px;font-weight:550;margin:0 0 3px}.meta{font-size:11px;color:var(--muted);overflow-wrap:anywhere}.kpis{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--line);border-radius:5px;margin:28px 0}.kpis div{padding:18px 22px;background:var(--surface);border-right:1px solid var(--line)}.kpis div:last-child{border:0}.kpis span{display:block;font-size:12px;color:var(--muted)}.kpis strong{font-size:30px;font-weight:450;font-variant-numeric:tabular-nums}.toolbar{display:flex;align-items:center;justify-content:space-between;margin:24px 0 12px}.filters{display:flex;gap:4px}button{background:transparent;color:var(--muted);border:1px solid transparent;border-radius:4px;padding:5px 10px;cursor:pointer;font:12px system-ui}button[aria-pressed=true],button:hover{color:var(--text);background:#18181b;border-color:var(--line)}button:focus-visible,summary:focus-visible{outline:2px solid #a1a1aa;outline-offset:3px}.findings{border:1px solid var(--line);border-radius:5px;overflow:hidden}.finding{display:grid;grid-template-columns:140px minmax(0,1fr);padding:20px;gap:16px;border-bottom:1px solid var(--line);background:var(--surface)}.finding:last-child{border:0}.finding[hidden]{display:none}.pill{font-size:10px;font-weight:600;display:inline-block;padding:1px 7px;border:1px solid;border-radius:4px}.critical{color:#f6a4a4;background:#b93b3b16;border-color:#803737}.high{color:#e8b67a;background:#b87a2912;border-color:#6c502f}.medium{color:#e4cf92;background:#b4a04012;border-color:#635b38}.rule{display:block;font-size:11px;color:var(--muted);margin-top:8px}.location{font-size:12px;color:var(--muted);overflow-wrap:anywhere}pre{background:#18181b;border:1px solid var(--line);padding:9px 12px;font-size:11px;white-space:pre-wrap;overflow-wrap:anywhere;margin:10px 0}.fix{color:var(--muted);font-size:12px;margin:8px 0 0}.panel{border:1px solid var(--line);border-radius:5px;margin-top:22px;padding:18px 20px;background:var(--surface)}.plan{white-space:pre-wrap;color:var(--muted);font-size:13px}summary{cursor:pointer;font-size:13px;font-weight:550}.trace{max-height:520px;overflow:auto}footer{display:flex;justify-content:space-between;color:var(--muted);font-size:11px;border-top:1px solid var(--line);padding:16px 0;margin-top:28px}.error{color:#f6a4a4}.empty{padding:20px;color:var(--muted)}@media(max-width:640px){header{padding:14px 18px;flex-wrap:wrap;gap:8px}main{padding:0 16px;margin-top:24px}.finding{grid-template-columns:1fr}.rule{display:inline;margin-left:12px}.kpis div{padding:12px}.kpis strong{font-size:24px}.toolbar{display:block}.badge{margin-left:0}}
</style></head><body>'''
    document += f'''<header><div class="brand">MinionAudit<span>/ {e(Path(run['repo']).name)}</span></div><div class="badge">{e(baseline)}</div></header><main><div class="eyebrow">Repository security review</div><h1>{e(Path(run['repo']).name)}</h1><div class="meta">{e(run['timestamp'])} · {e(run['model'] or 'Provider not initialized')}<br>{e(run['repo'])}</div><section class="kpis" aria-label="Finding counts">{kpis}</section>
<div class="toolbar"><h2>Findings <span class="meta" id="count">{len(run['findings'])}</span></h2><div class="filters" aria-label="Filter findings">'''
    document += "".join(f'<button type="button" aria-pressed="{str(s == "All").lower()}" data-filter="{s}">{s}</button>' for s in ["All", "Critical", "High", "Medium"])
    document += f'''</div></div><section class="findings">{rows or '<p class="empty">No findings recorded. Check run status and coverage before interpreting this result.</p>'}</section><p class="meta" id="empty" hidden>No findings match this filter.</p><p class="meta">Heuristic review candidates · {run.get('files_scanned', 0)} files read · Status: {e(run['status'])}. Resolved compares pre-fix scans; .env presence remains a finding after an ignore rule is added.</p>
<div class="error">{e(run.get('error', ''))}</div>{warnings}<section class="panel"><h2>Remediation review</h2><div class="plan">{e(run.get('remediation') or 'No completed model review available.')}</div></section>
<details class="panel"><summary>SDK Diagnostics &amp; Trace · OpenMinion 0.1.22 · {run['elapsed_seconds']}s</summary><p class="meta">SDK result statistics and metadata, actual tool execution, memory operations, delegation, and operator decisions. Missing token statistics are not estimated.</p><pre class="trace">{e(json.dumps(run['trace'], indent=2, default=str))}</pre></details><footer><span>LOCAL AUDIT / {e(run['session'])}</span><span>OpenMinion × NVIDIA NIM</span></footer></main>
<script>document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{{let count=0;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelectorAll('[data-severity]').forEach(row=>{{row.hidden=button.dataset.filter!=='All'&&row.dataset.severity!==button.dataset.filter;if(!row.hidden)count++;}});document.getElementById('count').textContent=count;document.getElementById('empty').hidden=count!==0;}}));</script></body></html>'''
    document = document.replace('<div class="badge">',
        f'<div class="meta">{e(run["timestamp"])}<br>{e(run["model"] or "Provider not initialized")}</div><div class="badge">', 1)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(document, encoding="utf-8")
    path.with_suffix(".json").write_text(json.dumps(run, indent=2, default=str), encoding="utf-8")
